1	/**
2	 * MELEE asset-recreation loop as a pi extension.
3	 *
4	 * Launch:
5	 *   pi -e apps/pi-asset-loop/extensions/asset-loop.ts \
6	 *      --asset runs/test-1/assets/asset_03
7	 *
8	 * The main agent writes component.html + component.css, calls `render` to
9	 * produce render.png, then calls `critique` — an isolated vision-capable
10	 * sub-agent that returns a structured issue list. The main agent fixes every
11	 * issue and renders again. Loop terminates on empty issue list or iteration cap.
12	 */
13	
14	import { readFileSync, writeFileSync } from "node:fs";
15	import { basename } from "node:path";
16	import type { ExtensionAPI, ExtensionContext } from "@mariozechner/pi-coding-agent";
17	import { Type } from "@sinclair/typebox";
18	
19	import { resolveAsset, type ResolvedAsset } from "../src/args.ts";
20	import { buildRenderWrapper } from "../src/wrapper.ts";
21	import { renderWithPlaywright } from "../src/renderer.ts";
22	import { buildSystemPrompt } from "../src/systemPrompt.ts";
23	import { readPngSize } from "../src/pngSize.ts";
24	import { runCritique, type CritiqueIssue, type CritiqueResult, type IssueSeverity } from "../src/critic.ts";
25	
26	const MAX_ITERATIONS = 15;
27	const MODEL_CANDIDATES: Array<{ provider: string; id: string }> = [
28	  { provider: "anthropic", id: "claude-opus-4-7" },
29	];
30	
31	export default function assetLoop(pi: ExtensionAPI) {
32	  pi.registerFlag("asset", {
33	    description: "Path to an asset dir, or a bare id when combined with --run.",
34	    type: "string",
35	  });
36	  pi.registerFlag("run", {
37	    description: "Run dir containing assets/<id>/ (only needed when --asset is a bare id).",
38	    type: "string",
39	  });
40	
41	  let resolved: ResolvedAsset | null = null;
42	  let referenceBase64: string | null = null;
43	  let referenceWidth = 0;
44	  let referenceHeight = 0;
45	  let assetJsonText = "";
46	  let extractionPromptText = "";
47	  let iteration = 0;
48	  let accepted = false;
49	  let lastCritique: CritiqueResult | null = null;
50	  let renderedSinceLastCritique = false;
51	  let critiquedSinceLastRender = false;
52	  let toolsLine = "tools: —";
53	
54	  const issueCountsLine = (): string => {
55	    if (!lastCritique) return "issues: —";
56	    if (lastCritique.issues.length === 0) return "issues: none";
57	    return `issues: ${countBy(lastCritique.issues, "blocking")} blocking · ${countBy(lastCritique.issues, "major")} major · ${countBy(lastCritique.issues, "minor")} minor`;
58	  };
59	
60	  const issueStatusSuffix = (): string => {
61	    if (!lastCritique) return "";
62	    if (lastCritique.issues.length === 0) return " · issues: none";
63	    return ` · b:${countBy(lastCritique.issues, "blocking")} m:${countBy(lastCritique.issues, "major")} mn:${countBy(lastCritique.issues, "minor")}`;
64	  };
65	
66	  const refreshWidget = (ctx: ExtensionContext) => {
67	    if (!resolved) return;
68	    const lines = [
69	      `asset: ${resolved.assetId}`,
70	      `iter:  ${iteration}/${MAX_ITERATIONS}${accepted ? "  (accepted)" : ""}`,
71	      issueCountsLine(),
72	      toolsLine,
73	    ];
74	    ctx.ui.setStatus(
75	      "asset-loop",
76	      `${resolved.assetId} · iter ${iteration}/${MAX_ITERATIONS}${issueStatusSuffix()}${accepted ? " ✓" : ""}`,
77	    );
78	    ctx.ui.setWidget("asset-loop-progress", lines, { placement: "belowEditor" });
79	  };
80	
81	  pi.on("session_start", async (_event, ctx) => {
82	    resolved = resolveAsset({
83	      asset: pi.getFlag("asset") as string | undefined,
84	      run: pi.getFlag("run") as string | undefined,
85	      cwd: ctx.cwd,
86	    });
87	
88	    assetJsonText = readFileSync(resolved.assetJsonPath, "utf8");
89	    const referenceBuf = readFileSync(resolved.extractedPngPath);
90	    referenceBase64 = referenceBuf.toString("base64");
91	    const dims = readPngSize(referenceBuf);
92	    referenceWidth = dims.width;
93	    referenceHeight = dims.height;
94	
95	    const sourceBase64 = readFileSync(resolved.sourcePngPath).toString("base64");
96	    extractionPromptText = readFileSync(resolved.extractionPromptPath, "utf8");
97	
98	    await pickModel(pi, ctx);
99	    pi.setThinkingLevel("high");
100	
101	    const allNames = pi.getAllTools().map((t) => t.name).sort();
102	    const activeNames = new Set(pi.getActiveTools());
103	    toolsLine = `tools: ${allNames
104	      .map((n) => (activeNames.has(n) ? n : `${n}*`))
105	      .join(", ")}`;
106	    refreshWidget(ctx);
107	
108	    // Kick off the first turn with all four inputs the system prompt expects.
109	    pi.sendUserMessage([
110	      {
111	        type: "text",
112	        text: `Context for asset "${resolved.assetId}". Four inputs follow: source screenshot (ground truth in situ), extracted asset (native ${referenceWidth}x${referenceHeight}px; your primary render target), the extraction prompt that produced the extracted asset, and asset metadata (already in the system prompt). Read all four before writing code.\n\nExtraction prompt that produced the extracted image:\n\n${extractionPromptText}`,
113	      },
114	      { type: "text", text: "Source screenshot (ground truth in situ):" },
115	      { type: "image", data: sourceBase64, mimeType: "image/png" },
116	      { type: "text", text: "Extracted asset (your primary render target):" },
117	      { type: "image", data: referenceBase64, mimeType: "image/png" },
118	    ]);
119	  });
120	
121	  pi.on("before_agent_start", async (_event, _ctx) => {
122	    if (!resolved) return;
123	    const prompt = buildSystemPrompt({
124	      assetId: resolved.assetId,
125	      assetDir: resolved.assetDir,
126	      assetJson: assetJsonText,
127	      referenceWidth,
128	      referenceHeight,
129	      maxIterations: MAX_ITERATIONS,
130	    });
131	    return { systemPrompt: prompt };
132	  });
133	
134	  pi.on("tool_call", async (event, _ctx) => {
135	    if (event.toolName === "render" && iteration >= MAX_ITERATIONS) {
136	      return {
137	        block: true,
138	        reason: `Max iterations (${MAX_ITERATIONS}) reached. Call \`accept\` with your current result.`,
139	      };
140	    }
141	
142	    // Any write/edit to component files invalidates the last critique.
143	    if (event.toolName === "write" || event.toolName === "edit") {
144	      const path = (event.input as { path?: unknown } | undefined)?.path;
145	      if (
146	        typeof path === "string" &&
147	        (path.endsWith("component.html") || path.endsWith("component.css"))
148	      ) {
149	        critiquedSinceLastRender = false;
150	      }
151	    }
152	
153	    return { block: false };
154	  });
155	
156	  pi.on("session_shutdown", async (_event, ctx) => {
157	    ctx.ui.setStatus("asset-loop", undefined);
158	    ctx.ui.setWidget("asset-loop-progress", undefined);
159	  });
160	
161	  pi.registerTool({
162	    name: "render",
163	    label: "Render asset",
164	    description:
165	      "Build the wrapper from the current component.html + component.css, screenshot #asset-root, write render.png, and return the extracted reference and the new render as inline images for comparison.",
166	    parameters: Type.Object({}),
167	    async execute(_toolCallId, _params, _signal, _onUpdate, ctx) {
168	      if (!resolved || !referenceBase64) {
169	        throw new Error("Extension not initialized; asset not resolved.");
170	      }
171	
172	      let componentHtml: string;
173	      let componentCss: string;
174	      try {
175	        componentHtml = readFileSync(resolved.componentHtmlPath, "utf8");
176	      } catch {
177	        throw new Error(
178	          `Missing ${basename(resolved.componentHtmlPath)}. Write it before calling render.`,
179	        );
180	      }
181	      try {
182	        componentCss = readFileSync(resolved.componentCssPath, "utf8");
183	      } catch {
184	        throw new Error(
185	          `Missing ${basename(resolved.componentCssPath)}. Write it before calling render.`,
186	        );
187	      }
188	
189	      writeFileSync(resolved.wrapperPath, buildRenderWrapper(componentHtml, componentCss));
190	
191	      await renderWithPlaywright({
192	        wrapperPath: resolved.wrapperPath,
193	        renderPath: resolved.renderPath,
194	        referenceWidth,
195	        referenceHeight,
196	      });
197	
198	      const renderBase64 = readFileSync(resolved.renderPath).toString("base64");
199	      iteration += 1;
200	      renderedSinceLastCritique = true;
201	      critiquedSinceLastRender = false;
202	      refreshWidget(ctx);
203	
204	      return {
205	        content: [
206	          {
207	            type: "text" as const,
208	            text: `Iteration ${iteration}/${MAX_ITERATIONS}. Reference (native ${referenceWidth}x${referenceHeight}) first, current render second. Call \`critique\` to get the issue list.`,
209	          },
210	          { type: "image" as const, data: referenceBase64, mimeType: "image/png" },
211	          { type: "image" as const, data: renderBase64, mimeType: "image/png" },
212	        ],
213	        details: {
214	          iteration,
215	          maxIterations: MAX_ITERATIONS,
216	          renderPath: resolved.renderPath,
217	        },
218	      };
219	    },
220	  });
221	
222	  pi.registerTool({
223	    name: "critique",
224	    label: "Critique render",
225	    description:
226	      "Launch an isolated critic agent with the source screenshot, extracted reference, the current render.png, the extraction prompt, and asset.json. Returns a structured JSON issue list (blocking/major/minor severities). The critic is the scoring authority — fix every issue it reports, then render + critique again. Loop terminates when issues is empty. Gate: you must have rendered since the last critique.",
227	    parameters: Type.Object({}),
228	    async execute(_toolCallId, _params, _signal, _onUpdate, ctx) {
229	      if (!resolved) {
230	        throw new Error("Extension not initialized; asset not resolved.");
231	      }
232	      if (!renderedSinceLastCritique) {
233	        throw new Error(
234	          "No new render since the last critique. Call `render` first, then `critique`.",
235	        );
236	      }
237	      if (!ctx.model) {
238	        throw new Error("No model configured; cannot run critic.");
239	      }
240	      const auth = await ctx.modelRegistry.getApiKeyAndHeaders(ctx.model);
241	      if (!auth.ok) {
242	        throw new Error(`Cannot resolve credentials for critic: ${auth.error}`);
243	      }
244	
245	      const result = await runCritique({
246	        model: ctx.model,
247	        auth: { apiKey: auth.apiKey, headers: auth.headers },
248	        sourcePngPath: resolved.sourcePngPath,
249	        extractedPngPath: resolved.extractedPngPath,
250	        renderPngPath: resolved.renderPath,
251	        extractionPromptText,
252	        assetJson: assetJsonText,
253	        signal: ctx.signal,
254	      });
255	
256	      lastCritique = result;
257	      renderedSinceLastCritique = false;
258	      critiquedSinceLastRender = true;
259	
260	      const persisted = {
261	        iteration,
262	        verdict: result.verdict,
263	        issues: result.issues,
264	      };
265	      writeFileSync(resolved.critiqueJsonPath, `${JSON.stringify(persisted, null, 2)}\n`);
266	
267	      refreshWidget(ctx);
268	
269	      return {
270	        content: [
271	          {
272	            type: "text" as const,
273	            text: formatCritiqueForAgent(result, iteration, MAX_ITERATIONS),
274	          },
275	        ],
276	        details: persisted,
277	      };
278	    },
279	  });
280	
281	  pi.registerTool({
282	    name: "accept",
283	    label: "Accept asset",
284	    description:
285	      "Call when the critic returns zero issues, or when you have hit the iteration cap. Writes accepted.json and shuts down the session. Blocked if there is no fresh critique for the current render, or if the critic still has issues and you have iterations remaining.",
286	    parameters: Type.Object({
287	      notes: Type.Array(Type.String(), {
288	        description:
289	          "Short notes for the record: residual defects (if accepting at cap), raster fallbacks used, anything a later reviewer should know.",
290	      }),
291	    }),
292	    async execute(_toolCallId, params, _signal, _onUpdate, ctx) {
293	      if (!resolved) {
294	        throw new Error("Extension not initialized; asset not resolved.");
295	      }
296	      if (!critiquedSinceLastRender || !lastCritique) {
297	        throw new Error(
298	          "No fresh critique for the current render. Call `render` then `critique` before accepting.",
299	        );
300	      }
301	      const outstandingIssues = lastCritique.issues;
302	      const hitEmpty = outstandingIssues.length === 0;
303	      if (!hitEmpty && iteration < MAX_ITERATIONS) {
304	        throw new Error(
305	          `Critic still reports ${outstandingIssues.length} issue(s) and you have ${MAX_ITERATIONS - iteration} render(s) left. Fix the issues, render, and critique again.`,
306	        );
307	      }
308	
309	      const payload = {
310	        asset_id: resolved.assetId,
311	        iterations: iteration,
312	        max_iterations: MAX_ITERATIONS,
313	        hit_empty_issues: hitEmpty,
314	        residual_issues: outstandingIssues,
315	        verdict: lastCritique.verdict,
316	        notes: params.notes,
317	        accepted_at: new Date().toISOString(),
318	      };
319	      writeFileSync(resolved.acceptedJsonPath, `${JSON.stringify(payload, null, 2)}\n`);
320	      accepted = true;
321	      refreshWidget(ctx);
322	      ctx.shutdown();
323	
324	      const reason = hitEmpty
325	        ? "critic returned zero issues"
326	        : `iteration cap reached with ${outstandingIssues.length} residual issue(s)`;
327	      return {
328	        content: [
329	          {
330	            type: "text" as const,
331	            text: `Accepted asset ${resolved.assetId} after ${iteration} iteration(s) — ${reason}. Wrote ${resolved.acceptedJsonPath}.`,
332	          },
333	        ],
334	        details: payload,
335	      };
336	    },
337	  });
338	}
339	
340	function countBy(issues: CritiqueIssue[], severity: IssueSeverity): number {
341	  let n = 0;
342	  for (const i of issues) if (i.severity === severity) n++;
343	  return n;
344	}
345	
346	function formatCritiqueForAgent(
347	  result: CritiqueResult,
348	  iteration: number,
349	  maxIterations: number,
350	): string {
351	  const lines: string[] = [];
352	  lines.push(`Critique for iteration ${iteration}/${maxIterations}.`);
353	  lines.push(`Verdict: ${result.verdict || "(none)"}`);
354	  lines.push("");
355	  if (result.issues.length === 0) {
356	    lines.push("Issues: none. The critic has no defects to report — call `accept`.");
357	    return lines.join("\n");
358	  }
359	  const b = countBy(result.issues, "blocking");
360	  const m = countBy(result.issues, "major");
361	  const mn = countBy(result.issues, "minor");
362	  lines.push(`Issues: ${b} blocking · ${m} major · ${mn} minor. Fix every blocking and major issue, and every minor unless fixing would regress something else. Then call \`render\` and \`critique\` again.`);
363	  lines.push("");
364	  for (const severity of ["blocking", "major", "minor"] as const) {
365	    const group = result.issues.filter((i) => i.severity === severity);
366	    if (group.length === 0) continue;
367	    lines.push(`${severity.toUpperCase()}:`);
368	    for (const issue of group) {
369	      lines.push(`  [${issue.id}] region=${issue.region}`);
370	      lines.push(`    ${issue.description}`);
371	      if (issue.fix_hint) lines.push(`    fix_hint: ${issue.fix_hint}`);
372	    }
373	    lines.push("");
374	  }
375	  return lines.join("\n").trimEnd();
376	}
377	
378	async function pickModel(pi: ExtensionAPI, ctx: ExtensionContext): Promise<void> {
379	  for (const candidate of MODEL_CANDIDATES) {
380	    const model = ctx.modelRegistry.find(candidate.provider, candidate.id);
381	    if (!model) continue;
382	    const ok = await pi.setModel(model);
383	    if (ok) {
384	      if (candidate.id !== MODEL_CANDIDATES[0]!.id) {
385	        ctx.ui.notify(
386	          `Using ${candidate.provider}/${candidate.id} (preferred ${MODEL_CANDIDATES[0]!.id} unavailable).`,
387	          "warning",
388	        );
389	      }
390	      return;
391	    }
392	  }
393	  ctx.ui.notify(
394	    `${MODEL_CANDIDATES[0]!.id} unavailable. Falling back to current model.`,
395	    "error",
396	  );
397	}
